const startBtn=document.getElementById("start-btn"),introScreen=document.getElementById("intro-screen"),gameScreen=document.getElementById("game-screen"),stageContent=document.getElementById("stage-content"),sounds={success:[],failure:[],shock:[],beep:[]};function createSoundPool(n,e,t=5){for(let a=0;a<t;a++)sounds[n].push(new Audio(e))}createSoundPool("success","assets/sounds/success.mp3",3),createSoundPool("failure","assets/sounds/failure.mp3",3),createSoundPool("shock","assets/sounds/shock.mp3",3),createSoundPool("beep","assets/sounds/beep.mp3",8);const soundIndex={success:0,failure:0,shock:0,beep:0};function playSound(n){const e=sounds[n];if(!e)return;const t=e[soundIndex[n]];t.currentTime=0,t.play(),soundIndex[n]=(soundIndex[n]+1)%e.length}const alarmSound=new Audio("assets/sounds/alarm.mp3");function startAlarm(){alarmSound.currentTime=0,alarmSound.play()}function stopAlarm(){alarmSound.pause(),alarmSound.currentTime=0}let stageIndex=0,completedStage=0;function startGame(){updatePatientState("critical"),startAlarm(),introScreen.classList.remove("active"),gameScreen.classList.add("active"),transition("📡 Connecting Emergency System","Loading medical equipment...",(()=>{stopAlarm(),loadStage()}))}function loadStage(){const n=GAME_DATA.stages[stageIndex];updateHUD(stageIndex,n),"final"!==n?showStageBriefing(n,(()=>{switch(n){case"devices":startStage1();break;case"ecg":startStage2();break;case"repair":startStage3();break;case"stabilize":startStage4();break}})):showVictory()}function gameOver(n){playSound("failure"),stopAlarm(),document.getElementById("timer").textContent="",stageContent.innerHTML=`\n\n\n        <div class="card">\n\n\n            <h1>\n                💀 GAME OVER\n            </h1>\n\n\n            <br>\n\n\n            <p>\n                ${n}\n            </p>\n\n\n            <br>\n\n\n\n            <button\n                onclick="location.reload()">\n\n\n                Try Again\n\n\n            </button>\n\n\n\n        </div>\n\n\n    `}function transition(n,e,t){document.getElementById("timer").textContent="",stageContent.innerHTML=`\n\n\n        <div class="card transition-card">\n\n\n            <h1>\n\n                ${n}\n\n            </h1>\n\n\n            <br>\n\n\n            <p>\n\n                ${e}\n\n            </p>\n\n\n        </div>\n\n\n    `,setTimeout(t,1800)}function shuffle(n){for(let e=n.length-1;e>0;e--){const t=Math.floor(Math.random()*(e+1));[n[e],n[t]]=[n[t],n[e]]}return n}function stageCompleted(){completeMission("stage"+completedStage);const n=[null,"afterStage1","afterStage2","afterStage3","afterStage4"][completedStage];n?showDialogue(n,(()=>{4!==completedStage?(stageIndex++,loadStage()):showMissionReport()})):(stageIndex++,loadStage())}startBtn.addEventListener("click",startGame);